import java.util.Scanner;

public class Main {
    static final int MAX_SIZE = 1000007;
    static final long MOD_CONST = 1000000007L;
    static boolean[] visited_nodes = new boolean[MAX_SIZE];
    static long[] count_divisors = new long[MAX_SIZE];
    static long[] cycle_lengths_arr = new long[MAX_SIZE];
    static long[] dp_vals = new long[MAX_SIZE];

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long answer = 1;
        int p = sc.nextInt();
        int k = sc.nextInt();

        for (int i = 0; i < p; i++) {
            if (!visited_nodes[i]) {
                int length = 0;
                long current = i;
                while (!visited_nodes[(int) current]) {
                    visited_nodes[(int) current] = true;
                    current = (k * current) % p;
                    length++;
                }
                cycle_lengths_arr[length]++;
            }
        }

        for (int i = 1; i <= p; i++) {
            dp_vals[i] = (cycle_lengths_arr[i] * i) % MOD_CONST;
        }

        for (int i = 1; i <= p; i++) {
            count_divisors[i] = (count_divisors[i] + dp_vals[i]) % MOD_CONST;
            for (int j = i + i; j <= p; j += i) {
                count_divisors[j] = (dp_vals[i] + count_divisors[j]) % MOD_CONST;
            }
        }

        for (int i = 1; i <= p; i++) {
            if (i == 1) {
                for (int j = 0; j < cycle_lengths_arr[i] - 1; j++) {
                    answer = (answer * cycle_lengths_arr[i]) % MOD_CONST;
                }
            } else {
                for (int j = 0; j < cycle_lengths_arr[i]; j++) {
                    answer = (answer * count_divisors[i]) % MOD_CONST;
                }
            }
        }

        if (k == 1) {
            answer = (answer * count_divisors[1]) % MOD_CONST;
        }

        System.out.println(answer);
        sc.close();
    }
}
